/**
 * Copy of backend/src/analysis/catalog.ts: the same 10 judgments (ids, titles, wording).
 * Catalogue of the judgments sent to Jev (TypeSafe System One). Each entry is ONE narrow
 * question with explicit criteria. The code owns the flow: Jev only returns typed judgments
 * (Choice / Noul / Score); the plain-language reading shown to the user comes from the
 * templates below, never from free text generated by the model. Wellness tone, not medical.
 */
export type JudgmentKind = "choice" | "noul" | "score";

export type CatalogEntry = {
  /** Stable id (also the key of the question in the API call and in results_json). */
  id: string;
  title: string;
  kind: JudgmentKind;
  /** Short description for the UI (what is being asked, in the user's words). */
  description: string;
  /** Question for Jev; points to fields of the state with `backticks` paths. */
  instructions: string;
  /** choice: option -> description. noul: optional true/false. score: ordered levels. */
  choiceCriteria?: Record<string, string>;
  noulCriteria?: { true: string; false: string };
  scoreLevels?: string[];
  /** Plain-language readings. */
  readings: {
    /** noul: [low (<0.35), uncertain, high (>0.65)] */
    noul?: [string, string, string];
    /** score: one per level (index = round(position)). */
    score?: string[];
    /** choice: option -> text. */
    choice?: Record<string, string>;
  };
};

