export const CATALOG_BY_ID = new Map(CATALOG.map((c) => [c.id, c]));

export function publicCatalog() {
  return CATALOG.map((c) => ({
    id: c.id,
    title: c.title,
    kind: c.kind,
    description: c.description,
  }));
}

